const CACHE='tileforge-0.4.3-studio-1';const ASSETS=['./','./index.html','./editor.html','./style.css','./studio.css','./layout.css','./layout.mjs','./workflow.mjs','./drafts.mjs','./border.mjs','./studio.mjs','./project.mjs','./reviewed-categories.mjs','./guide.html','./app.mjs','./core.mjs','./vendor/fflate.mjs','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest'].map(p=>/\.(?:mjs|css)$/.test(p)?p+'?v=0.4.3':p);self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('tileforge-')&&k!==CACHE).map(k=>caches.delete(k)))));});self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin||new URL(e.request.url).pathname.endsWith('.apk'))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request)));});
